import java.io.*;
import java.util.*;

public class SecureResourceExample {
    public static void main(String[] args) {
        // Correct approach: Use try-with-resources for automatic resource cleanup.
        Stream<String> passwordStreams = Arrays.stream(
            FileReader.open("passwords.txt"),
            ReaderWriter.open("credentials.txt")
        );

        for (String line : passwordStreams) {
            // Properly handle null checks and string concatenation safely.
            System.out.println(line.trim());
        }
    }
}
